INSERT INTO `service_type_blocks` (`service_type_id`, `block_slug`, `block_title`, `category`, `display_order`, `default_content`, `allowed_vars`) VALUES
(19, 'cabecalho', 'Cabeçalho', 'layout', 0, NULL, '["Cidade","DataExtenso","numero_proposta"]'),
(19, 'apresentacao_drone', '1. Apresentação', 'presentation', 1, '<p>A <strong>${Empresa}</strong> apresenta esta proposta técnica para execução de <strong>Levantamento Planialtimétrico via Aerofotogrametria com Drones (VANTs)</strong>.</p><p>Trata-se de <strong>Engenharia de Precisão</strong>, não simples filmagem aérea. Geramos representação digital fiel do terreno com coordenadas exatas (Lat, Long, Altitude) para base legal de projetos.</p>', '["Empresa"]'),
(19, 'finalidade_drone', '2. Finalidade', 'presentation', 2, '<p>Obter mapeamento aéreo detalhado, ortomosaicos georreferenciados, Modelo Digital de Terreno (MDT) e nuvens de pontos densas para análise, planejamento e cálculo de volumes.</p>', '["area_obra","finalidade"]'),
(19, 'escopo_drone', '3. Escopo do Serviço', 'technical', 3, '<h4>Área de Abrangência</h4><p>Levantamento fotogramétrico da área de <strong>${area_obra}</strong>, compreendendo:</p><ul><li>Captura de imagens aéreas com sobreposição longitudinal 80% e lateral 70%;</li><li>Implantação de pontos de controle terrestre (GCPs) com GPS RTK;</li><li>Processamento fotogramétrico e geração de ortomosaico;</li><li>Extração de curvas de nível e elementos vetoriais.</li></ul>', '["area_obra"]'),
(19, 'metodologia_drone', '4. Metodologia', 'technical', 4, '<h4>Etapa 1: Planejamento de Voo (Escritório)</h4><p>Estudo prévio da área via satélite, definição de altura de voo (GSD desejado) e programação da grade de cobertura.</p><h4>Etapa 2: Apoio Terrestre - GCPs (Campo)</h4><p>Distribuição de alvos no terreno e coleta de coordenadas com GPS Geodésico de alta precisão (RTK). Estes pontos "ancoram" o ortomosaico com precisão centimétrica.</p><h4>Etapa 3: Execução do Voo (Campo)</h4><p>Checklist de segurança (DECEA, baterias, meteorologia). O drone executa rota autônoma capturando imagens em ângulos nadir e oblíquos.</p><h4>Etapa 4: Processamento Fotogramétrico (Escritório)</h4><p>Software especializado: alinhamento de fotos, geração da nuvem de pontos densa, georreferenciamento com GCPs e ortorretificação.</p><h4>Etapa 5: Vetorização e CAD (Escritório)</h4><p>Desenhista vetoriza elementos do terreno (construções, cercas, vegetação) e gera curvas de nível no software CAD.</p>', '[]'),
(19, 'documentacao_drone', '5. Documentação Gerada', 'technical', 5, '<ul><li><strong>Ortomosaico Georreferenciado:</strong> Imagem raster em alta resolução (TIF/JPG) com arquivo de georreferenciamento (TFW/JGW);</li><li><strong>MDT (Modelo Digital de Terreno):</strong> Superfície 3D do solo nu em formato compatível com softwares de terraplenagem;</li><li><strong>Curvas de nível:</strong> Arquivo CAD (DWG/DXF) com equidistância conforme especificação;</li><li><strong>Planta Topográfica:</strong> PDF técnico com legenda, escala, norte e memorial;</li><li><strong>Relatório de Processamento:</strong> Estatísticas de precisão (erro médio quadrado);</li><li><strong>ART:</strong> Anotação de Responsabilidade Técnica registrada no CREA.</li></ul>', '[]'),
(19, 'equipamentos_drone', '6. Equipamentos', 'technical', 6, '<ul><li><strong>Drone:</strong> ${Drone} (câmera de alta resolução, RTK embutido);</li><li><strong>GPS de Apoio:</strong> ${GPS} (coleta de GCPs com precisão centimétrica);</li><li><strong>Estação Total:</strong> ${Estacao_Total} (verificação de pontos de controle);</li><li><strong>Veículo:</strong> ${Veiculo} (transporte da equipe e equipamentos).</li></ul>', '["Drone","GPS","Estacao_Total","Veiculo"]'),
(19, 'cronograma_drone', '7. Cronograma', 'technical', 7, '<table class="proposal-table"><thead><tr><th>Etapa</th><th>Descrição</th><th>Prazo</th></tr></thead><tbody><tr><td>Mobilização</td><td>Planejamento e deslocamento</td><td>Até 02 dias</td></tr><tr><td>Campo</td><td>Instalação de GCPs e voos</td><td>${dias_campo} dia(s)</td></tr><tr><td>Processamento</td><td>Geração de nuvem e ortomosaico</td><td>03 a 05 dias</td></tr><tr><td>Vetorização</td><td>CAD e planta final</td><td>${dias_escritorio} dia(s)</td></tr><tr class="total"><td colspan="2"><strong>TOTAL ESTIMADO</strong></td><td><strong>${prazo_execucao}</strong></td></tr></tbody></table>', '["prazo_execucao","dias_campo","dias_escritorio"]'),
(19, 'investimento', '8. Investimento', 'financial', 8, NULL, '["ValorProposta","ValorExtenso"]'),
(19, 'condicoes_pagamento', '9. Condições de Pagamento', 'financial', 9, NULL, '["mobilizacao_percentual","mobilizacao_valor","restante_percentual","restante_valor"]'),
(19, 'dados_bancarios', '10. Dados Bancários', 'financial', 10, NULL, '["Banco","Agencia","Conta","PIX"]'),
