(19, 'rodape', 'Rodapé', 'layout', 99, NULL, '["Empresa","CNPJ","whatsapp"]'),
(13, 'cabecalho', 'Cabeçalho', 'layout', 0, NULL, '["Cidade","DataExtenso","numero_proposta"]'),
(13, 'apresentacao_padrao', '1. Apresentação', 'presentation', 1, '<p>A <strong>${Empresa}</strong> é empresa especializada em soluções de Engenharia e Topografia, atuando com equipamentos de alta tecnologia e equipe técnica qualificada.</p><p>Nosso objetivo é fornecer dados precisos e confiáveis, seguindo rigorosamente as normas técnicas da ABNT NBR 13.133.</p>', '["Empresa"]'),
(13, 'finalidade_padrao', '2. Finalidade', 'presentation', 2, '<p>${finalidade}</p>', '["finalidade"]'),
(13, 'escopo_planialtimetrico', '3. Escopo do Serviço', 'technical', 3, '<h4>Levantamento Planialtimétrico Cadastral</h4><p>Execução de levantamento topográfico da área de <strong>${area_obra}</strong>, compreendendo:</p><ul><li>Demarcação do perímetro do imóvel;</li><li>Levantamento de todas as edificações, cercas, muros e benfeitorias;</li><li>Coleta de pontos cotados para geração de curvas de nível;</li><li>Identificação de elementos da rede de infraestrutura (postes, caixas, etc.).</li></ul>', '["area_obra"]'),
(13, 'metodologia_padrao', '4. Metodologia', 'technical', 4, '<h4>Etapa 1: Reconhecimento e Amarração Geodésica</h4><p>Implantação da rede de apoio com GPS GNSS de dupla frequência, vinculada ao Sistema Geodésico Brasileiro (SIRGAS 2000).</p><h4>Etapa 2: Levantamento de Detalhe</h4><p>Utilização de Estação Total para coleta irradiada de todos os elementos do terreno. Coleta de pontos para altimetria.</p><h4>Etapa 3: Processamento e CAD</h4><p>Processamento dos dados brutos, cálculos de poligonais, ajustamento e geração do desenho técnico em CAD.</p>', '[]'),
(13, 'documentacao_padrao', '5. Documentação Gerada', 'technical', 5, '<ul><li>Planta Topográfica Planialtimétrica (PDF e DWG);</li><li>Memorial Descritivo do perímetro;</li><li>ART registrada no CREA;</li><li>Relatório Fotográfico (quando aplicável).</li></ul>', '[]'),
(13, 'equipamentos_padrao', '6. Equipamentos', 'technical', 6, '<ul><li><strong>Estação Total:</strong> ${Estacao_Total};</li><li><strong>GPS/GNSS:</strong> ${GPS} (amarração geodésica);</li><li><strong>Veículo:</strong> ${Veiculo}.</li></ul>', '["Estacao_Total","GPS","Veiculo"]'),
(13, 'cronograma_padrao', '7. Prazo de Execução', 'technical', 7, '<p>O serviço será executado em <strong>${prazo_execucao}</strong>, divididos em:</p><ul><li><strong>Campo:</strong> ${dias_campo} dia(s) para coleta de dados;</li><li><strong>Escritório:</strong> ${dias_escritorio} dia(s) para processamento e desenho.</li></ul>', '["prazo_execucao","dias_campo","dias_escritorio"]'),
(13, 'investimento', '8. Investimento', 'financial', 8, NULL, '["ValorProposta","ValorExtenso"]'),
