(11, 'cabecalho', 'Cabeçalho', 'layout', 0, NULL, '["Cidade","DataExtenso"]'),
(11, 'apresentacao_usucapiao', '1. Apresentação', 'presentation', 1, '<p>A <strong>${Empresa}</strong> presta serviços de topografia legal para processos de usucapião, fornecendo documentação técnica exigida pelo Poder Judiciário e cartórios de registro de imóveis.</p>', '["Empresa"]'),
(11, 'finalidade_usucapiao', '2. Finalidade', 'presentation', 2, '<p>Fornecer a delimitação precisa do imóvel, com coordenadas georreferenciadas, para comprovar a <strong>posse contínua e pacífica</strong> e demonstrar a área ocupada no processo legal de usucapião.</p>', '[]'),
(11, 'escopo_usucapiao', '3. Escopo do Serviço', 'technical', 3, '<p>Levantamento planialtimétrico da área de <strong>${area_obra}</strong> com ênfase em:</p><ul><li>Identificação precisa dos limites e confrontantes;</li><li>Relação de benfeitorias existentes (casas, cercas, plantações);</li><li>Tempo de ocupação comprovado (quando houver documentos);</li><li>Memorial descritivo detalhado para embasar ação judicial.</li></ul>', '["area_obra"]'),
(11, 'metodologia_usucapiao', '4. Metodologia', 'technical', 4, '<p>Levantamento topográfico com GPS RTK e Estação Total, georreferenciado ao SIRGAS 2000. Prioridade à identificação de confrontantes e registro fotográfico datado.</p>', '[]'),
(11, 'documentacao_usucapiao', '5. Documentação para Processo Judicial', 'legal', 5, '<ul><li><strong>Planta Topográfica Georreferenciada:</strong> Com coordenadas dos vértices;</li><li><strong>Memorial Descritivo Detalhado:</strong> Com confrontantes e benfeitorias;</li><li><strong>Relatório Fotográfico:</strong> Fotos datadas do terreno e acessos;</li><li><strong>ART Específica:</strong> Com menção ao processo de usucapião;</li><li><strong>Declaração Técnica:</strong> Sobre a ocupação do imóvel (se solicitado).</li></ul>', '[]'),
(11, 'investimento', '8. Investimento', 'financial', 8, NULL, '["ValorProposta","ValorExtenso"]'),
(11, 'condicoes_pagamento', '9. Condições de Pagamento', 'financial', 9, NULL, '["mobilizacao_percentual","mobilizacao_valor","restante_percentual","restante_valor"]'),
