(20, 'apresentacao_padrao', '1. Apresentação', 'presentation', 1, '<p>A <strong>${Empresa}</strong> é empresa especializada em soluções de Engenharia e Topografia, atuando com equipamentos de alta tecnologia e equipe técnica qualificada.</p><p>Nosso objetivo é fornecer dados precisos e confiáveis, seguindo rigorosamente as normas técnicas da ABNT NBR 13.133.</p>', '["Empresa"]'),
(20, 'finalidade_padrao', '2. Finalidade', 'presentation', 2, '<p>${finalidade}</p>', '["finalidade"]'),
(20, 'escopo_planialtimetrico', '3. Escopo do Serviço', 'technical', 3, '<h4>Levantamento Planialtimétrico Cadastral</h4><p>Execução de levantamento topográfico da área de <strong>${area_obra}</strong>, compreendendo:</p><ul><li>Demarcação do perímetro do imóvel;</li><li>Levantamento de todas as edificações, cercas, muros e benfeitorias;</li><li>Coleta de pontos cotados para geração de curvas de nível;</li><li>Identificação de elementos da rede de infraestrutura (postes, caixas, etc.).</li></ul>', '["area_obra"]'),
(20, 'metodologia_desdobramento', '4. Metodologia', 'technical', 4, '<h4>Etapa 1 a 3: Idênticas ao Levantamento Planialtimétrico</h4><p>Execução completa do levantamento planialtimétrico cadastral da área original.</p><h4>Etapa 4: Projeto de Loteamento (Escritório)</h4><p>Elaboração do projeto de divisão em lotes menores, respeitando zoneamento, áreas de preservação e acessos.</p><h4>Etapa 5: Locação das Novas Divisas (Campo)</h4><p><strong>Esta é a diferença crucial:</strong> Após aprovação do projeto preliminar, nossa equipe retorna ao campo para <strong>marcar fisicamente no terreno</strong> as novas divisas dos lotes com estacas de madeira ou pintura, permitindo que o cliente visualize o resultado antes da documentação final.</p><h4>Etapa 6: Documentação para Registro</h4><p>Memoriais descritivos individuais por lote, plantas de situação e processo de desdobro para cartório/prefeitura.</p>', '[]'),
(20, 'documentacao_padrao', '5. Documentação Gerada', 'technical', 5, '<ul><li>Planta Topográfica Planialtimétrica (PDF e DWG);</li><li>Memorial Descritivo do perímetro;</li><li>ART registrada no CREA;</li><li>Relatório Fotográfico (quando aplicável).</li></ul>', '[]'),
